**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int nwd(int a, int b) {
    while (b != 0) {
        int t = b;
        b = a % b;
        a = t;
    }
    return a;
}

int main() {
    ifstream plik("dane.txt");
    int x;
    vector<int> v;
    while (plik >> x) v.push_back(x);

    cout << "a) NWD par kolejnych liczb:" << endl;
    int maxNWD = 0, maxI = 0;
    int suma = 0;
    for (int i = 0; i < (int)v.size() - 1; i++) {
        int g = nwd(v[i], v[i + 1]);
        cout << "(" << v[i] << ", " << v[i + 1] << ") -> NWD = " << g << endl;
        suma += g;
        if (g > maxNWD) {
            maxNWD = g;
            maxI = i;
        }
    }

    cout << endl << "b) Para z max NWD: (" << v[maxI] << ", " << v[maxI + 1]
         << ") -> NWD = " << maxNWD << endl;
    cout << endl << "c) Suma NWD: " << suma << endl;
    return 0;
}
```

**Wyjasnienie**: NWD algorytmem Euklidesa: zamieniamy (a,b) na (b, a%b) az b=0. Iterujemy po parach kolejnych elementow wektora. Sledzimy max NWD i sumujemy wszystkie.

Weryfikacja NWD (algorytm Euklidesa):
- NWD(84,126): 84,126 -> 126%84=42, 84%42=0 -> 42
- NWD(126,210): 126,210 -> 210%126=84, 126%84=42, 84%42=0 -> 42
- NWD(210,315): 210,315 -> 315%210=105, 210%105=0 -> 105
- NWD(315,180): 315,180 -> 315%180=135, 180%135=45, 135%45=0 -> 45
- NWD(180,72): 180,72 -> 180%72=36, 72%36=0 -> 36
- NWD(72,240): 72,240 -> 240%72=24, 72%24=0 -> 24
- NWD(240,360): 240,360 -> 360%240=120, 240%120=0 -> 120
- NWD(360,150): 360,150 -> 360%150=60, 150%60=30, 60%30=0 -> 30
- NWD(150,225): 150,225 -> 225%150=75, 150%75=0 -> 75
- NWD(225,90): 225,90 -> 225%90=45, 90%45=0 -> 45
- NWD(90,270): 90,270 -> 270%90=0 -> 90

